feed:
GitLab Breaking Changes
{{ .Site.BaseURL }}update/deprecations/


Receive notifications of upcoming changes to GitLab that may affect your team's workflow.

  The GitLab Team

{{- $breakingChanges := where .Site.Data.deprecations.deprecations "breaking_change" true -}}
{{- $dated := slice -}}
{{- range $breakingChanges -}}
  {{- if .announcement_date -}}
    {{- $dated = $dated | append . -}}
  {{- end -}}
{{- end -}}
{{- $sorted := sort $dated "announcement_date" "desc" -}}
{{- if gt (len $sorted) 0 }}
{{ (index $sorted 0).announcement_date | time.AsTime | dateFormat "2006-01-02T15:04:05Z07:00" }}
{{- else }}
{{ now | dateFormat "2006-01-02T15:04:05Z07:00" }}
{{- end }}
{{- range $sorted }}
{{- $itemLink := "" -}}
{{- if .issue_url -}}
  {{- $itemLink = .issue_url -}}
{{- else if .documentation_url -}}
  {{- $itemLink = .documentation_url -}}
{{- else -}}
  {{- $itemLink = printf "%supdate/deprecations/#%s" $.Site.BaseURL (anchorize .title) -}}
{{- end }}
{{- $entryDate := .announcement_date | time.AsTime | dateFormat "2006-01-02T15:04:05Z07:00" }}

  {{ .title | plainify }}

  {{ $itemLink }}
  {{ $entryDate }}
  {{ $entryDate }}
  {{ .body | markdownify | replaceRE "" "]]]]>>" | safeHTML }}

{{- end }}
